<template><Layout><div class="breadcrumb"><Link :href="route('users.index')">Users</Link><span>›</span>{{ user.name }}</div><div class="page-header profile-header"><div><div class="eyebrow">USER PROFILE</div><h1>{{ user.name }}</h1><p>Member since {{ formatDate(user.created_at) }}</p></div><button class="delete-button" :disabled="deleting" @click="remove">{{ deleting?'Deleting…':'Delete user' }}</button></div><section class="profile-grid"><div><article class="detail-card profile-hero"><span class="profile-photo"><img v-if="user.image" :src="user.image"/><b v-else>{{ user.name.charAt(0) }}</b></span><div><h2>{{ user.name }}</h2><p>{{ user.phone||'No phone number' }}</p><span class="verification" :class="{pending:!user.is_approved}">{{ user.is_approved?'✓ Verified identity':'Unverified identity' }}</span></div></article><article class="detail-card"><header><h2>Contact information</h2></header><div class="info-grid"><div><span>Phone number</span><strong>{{ user.phone||'Not provided' }}</strong></div><div><span>Email address</span><strong>{{ user.email||'Not provided' }}</strong></div><div class="wide-info"><span>Address</span><strong>{{ user.address||'Not provided' }}</strong></div></div></article><article v-if="user.nrc_front_image||user.nrc_back_image" class="detail-card"><header><h2>Identity documents</h2><p>Private · administrator access only</p></header><div class="document-grid"><a v-if="user.nrc_front_image" :href="user.nrc_front_image" target="_blank"><img :src="user.nrc_front_image"/><span>NRC front ↗</span></a><a v-if="user.nrc_back_image" :href="user.nrc_back_image" target="_blank"><img :src="user.nrc_back_image"/><span>NRC back ↗</span></a></div></article></div><aside><article class="detail-card"><header><h2>Account overview</h2></header><div class="profile-metrics"><div><strong>{{ user.selling_products_count }}</strong><span>Listings</span></div><div><strong>{{ user.orders_count }}</strong><span>Orders</span></div><div><strong>{{ user.sell_count }}</strong><span>Sales</span></div><div><strong>{{ user.reward_points }}</strong><span>Points</span></div></div></article><article class="detail-card danger-card"><header><h2>Danger zone</h2></header><p>Deleting this user also removes their listings and associated buyer/seller orders. This action cannot be undone.</p><button class="delete-button" @click="remove">Delete account</button></article></aside></section></Layout></template>
<script setup>import{ref}from'vue';import{router}from'@inertiajs/vue3';import{route}from'ziggy-js';import Layout from'../Layouts/Layout.vue';const props=defineProps({user:Object}),deleting=ref(false);const formatDate=d=>new Intl.DateTimeFormat('en',{dateStyle:'long'}).format(new Date(d));const remove=()=>{if(!window.confirm(`Permanently delete ${props.user.name}? Their listings and orders will also be deleted.`))return;deleting.value=true;router.delete(route('users.destroy',props.user.id),{onFinish:()=>deleting.value=false})};</script>
